#!/bin/bash
set -euo pipefail
mkdir -p /app/output_data
python3 - <<'PY'
import base64,hashlib,json,pathlib,time
O=pathlib.Path('/app/output_data'); O.joinpath('solution.py').write_bytes(base64.b64decode('')); O.joinpath('provisional_checkpoint.json').write_text(json.dumps({'source_task_id':'coding:008','status':'equivalent_upstream_depth_4'})+'\n'); O.joinpath('preserved_source_facts.json').write_text(json.dumps({'source_task_id':'coding:008','preserved':True,'artifacts':['projects_and_members', 'task_status_history', 'messages_and_attachments', 'feedback_and_reports']})+'\n')
start=time.time(); probes={'solution.py':hashlib.sha256(O.joinpath('solution.py').read_bytes()).hexdigest()}; r={'schema_version':'async-rbench-event-receipt-v1','case_id':'mab-dependency-unblock-b999d1b968','source_task_id':'coding:008','event':'performance_metric_contract_completed','event_theme':'delayed_authoritative_result','meaning':'A delayed performance-metric contract fixes completion-rate, duration, and unique-assignment semantics after project, task, and communication state already exist.','authority':{'contract': 'team_performance_metric_contract_v2', 'duration_origin': 'task_created_at', 'assignment_policy': 'unique_member_per_task', 'report_formats': ['csv', 'pdf']},'worker_started_at':start,'worker_finished_at':time.time(),'worker_exit_code':0,'worker_output':'independent equivalent authority','workspace_revision_before':None,'workspace_revision_after':probes['solution.py'],'probes':probes}; r['receipt_sha256']=hashlib.sha256(json.dumps(r,sort_keys=True,separators=(',',':')).encode()).hexdigest(); O.joinpath('event_receipt.json').write_text(json.dumps(r,sort_keys=True)+'\n')
c={'schema_version': 'async-rbench-mab-source-closure-v1', 'case_id': 'mab-dependency-unblock-b999d1b968', 'source_task_id': 'coding:008', 'artifact_type': 'team_collaboration_performance_closure', 'event': 'performance_metric_contract_completed', 'upstream_depth': 4, 'preserved_workflows': ['projects_and_members', 'task_status_history', 'messages_and_attachments', 'feedback_and_reports'], 'source_semantics_reverified': True}; c['event_receipt_sha256']=r['receipt_sha256']; O.joinpath('coding_closure.json').write_text(json.dumps(c,sort_keys=True)+'\n'); m={'schema_version':'async-rbench-closure-v1','case_id':'mab-dependency-unblock-b999d1b968','source_task_id':'coding:008','event_receipt_sha256':r['receipt_sha256'],'event_consumed':True,'final_revision_sha256':probes['solution.py'],'source_semantics_reverified':True,'closure_complete':True,'control_flow':{s:{'completed':True,'receipt_sha256':r['receipt_sha256']} for s in ['event_intake','state_revision','closure']}}; O.joinpath('decision_manifest.json').write_text(json.dumps(m,sort_keys=True)+'\n')
